1	import { db } from "@/lib/db";
2	import { getCurrentUser } from "@/lib/auth";
3	import { runAgent, normalizePath, type FileMap } from "@/lib/agent";
4	import { buildSite, BuildError } from "@/lib/build-site";
5	import { chargeForBuild, costMicros, creditsFor, getBalance, getSpendCapStatus } from "@/lib/credits";
6	import { checkGenerateRateLimit } from "@/lib/rate-limit";
7	import { track, EVENTS } from "@/lib/events";
8	import { classifyFollowUp } from "@/lib/feedback-intent";
9	import { FLAGS, isEnabled } from "@/lib/flags";
10	
11	export const dynamic = "force-dynamic";
12	export const maxDuration = 300;
13	
14	function sse(event: unknown) {
15	  return `data: ${JSON.stringify(event)}\n\n`;
16	}
17	
18	// A build that fails to compile even after one repair attempt gives up — this
19	// bounds the worst case to ~2x the cost of a normal generation, not unbounded.
20	const MAX_BUILD_ATTEMPTS = 2;
21	
22	export async function POST(req: Request) {
23	  const user = await getCurrentUser();
24	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
25	
26	  const body = (await req.json().catch(() => null)) as {
27	    projectId?: string;
28	    prompt?: string;
29	    image?: string;
30	  } | null;
31	  const prompt = body?.prompt?.trim();
32	  if (!body?.projectId || !prompt) {
33	    return Response.json({ error: "Missing project or prompt." }, { status: 400 });
34	  }
35	
36	  // Only a data: URL (what the client-side downscale in PromptHero produces)
37	  // is accepted — anything else is silently dropped rather than passed on.
38	  const imageMatch = body.image?.match(/^data:(image\/(?:png|jpeg|webp));base64,(.+)$/);
39	  const image = imageMatch ? { mediaType: imageMatch[1], data: imageMatch[2] } : undefined;
40	
41	  const project = await db.project.findFirst({
42	    where: { id: body.projectId, userId: user.id },
43	    include: { messages: { orderBy: { createdAt: "asc" } } },
44	  });
45	  if (!project) return Response.json({ error: "Project not found." }, { status: 404 });
46	
47	  // ── Kill switch ──────────────────────────────────────────────────────────
48	  // Placed after the project lookup (so an unknown project still 404s, and the
49	  // switch never leaks the existence of someone else's project) and before
50	  // EVERY spend path below it: the balance read, the spend cap, the Build row,
51	  // the user Message row and the model call in runAgent. Refusing here writes
52	  // nothing at all and charges nothing at all.
53	  //
54	  // Its own status and its own words, deliberately. The two checks immediately
55	  // below both answer 402 and both talk about credits; reusing either would
56	  // tell the user they are out of money during an incident that has nothing to
57	  // do with their balance, and they would go and top up. 503 is the honest
58	  // code: the capability is temporarily withdrawn by us.
59	  //
60	  // Bucketed on user.id — stable per user, so a partial rollout (if this were
61	  // ever operated as one) cannot flip the same person between requests.
62	  if (!(await isEnabled(FLAGS.generation, user.id))) {
63	    return Response.json(
64	      {
65	        error:
66	          "Building is paused right now while we sort out a problem on our side. Nothing has been charged and your project is untouched — please try again in a few minutes.",
67	      },
68	      { status: 503 },
69	    );
70	  }
71	
72	  const balance = await getBalance(user.id);
73	  if (balance <= 0) {
74	    track(EVENTS.creditsExhausted, { userId: user.id, props: { projectId: project.id } });
75	    return Response.json(
76	      { error: "You're out of credits. Top up to keep building." },
77	      { status: 402 },
78	    );
79	  }
80	
81	  // The user's own ceiling, checked before anything is spent. Distinct from
82	  // running out of credits: they still HAVE the balance, they asked us not to
83	  // burn past this without them saying so. The message says exactly that, so
84	  // it never reads as a surprise limit we imposed.
85	  const cap = await getSpendCapStatus(user.id);
86	  if (cap.reached) {
87	    track(EVENTS.spendCapReached, {
88	      userId: user.id,
89	      props: { cap: cap.cap, spent: cap.spent, projectId: project.id },
90	    });
91	    return Response.json(
92	      {
93	        error: `You've hit your own spending cap of ${cap.cap} credits per 30 days (${cap.spent} used). Raise or remove it in Settings to keep building.`,
94	        spendCapReached: true,
95	      },
96	      { status: 402 },
97	    );
98	  }
99	
100	  const rateLimit = await checkGenerateRateLimit(user.id);
101	  if (!rateLimit.allowed) {
102	    return Response.json(
103	      { error: "You're generating too fast — take a short break and try again shortly." },
104	      { status: 429, headers: { "Retry-After": String(rateLimit.retryAfterSeconds) } },
105	    );
106	  }
107	
108	  // The foundation means source files are never empty — "first build" is
109	  // instead "first real customization request" for this project.
110	  const kind = project.messages.length === 0 ? "create" : "edit";
111	
112	  const build = await db.build.create({
113	    data: { projectId: project.id, status: "RUNNING", model: "", prompt },
114	  });
115	
116	  track(EVENTS.buildStarted, {
117	    userId: user.id,
118	    props: {
119	      buildId: build.id,
120	      projectId: project.id,
121	      kind,
122	      hasImage: Boolean(image),
123	      // Only meaningful on an edit — a first build has no prior output to be
124	      // reacting to. Left off `create` so followUpIntents() isn't diluted by
125	      // rows that were never follow-ups.
126	      ...(kind === "edit" ? { intent: classifyFollowUp(prompt) } : {}),
127	    },
128	  });
129	
130	  await db.message.create({
131	    data: { projectId: project.id, role: "user", content: prompt },
132	  });
133	
134	  // Aborted when the client disconnects (tab closed, network drop) — cancels
135	  // the in-flight Anthropic request instead of burning tokens for nobody.
136	  const abortController = new AbortController();
137	
138	  const encoder = new TextEncoder();
139	  const stream = new ReadableStream({
140	    async start(controller) {
141	      // A client disconnect races with our own sends: enqueue on a closed
142	      // controller throws "Controller is already closed", which used to be
143	      // caught as a generic failure and wrongly mark an otherwise-fine build
144	      // FAILED. There's nothing to do about a gone client — swallow it.
145	      const send = (event: unknown) => {
146	        try {
147	          controller.enqueue(encoder.encode(sse(event)));
148	        } catch {
149	          // client is gone
150	        }
151	      };
152	
153	      let filesWritten = 0;
154	      let succeeded = false;
155	      // 0 means it compiled first try. This is the raw material for the
156	      // green-build-first-try metric (see greenBuildRate in lib/events.ts),
157	      // which the roadmap treats as a gate but nothing measured before.
158	      // Declared out here so the catch below can record it too.
159	      let repairAttempts = 0;
160	      const totals = { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 };
161	      let model = "";
162	      let lastReply = "";
163	      let lastProgress = "";
164	
165	      const readSourceFiles = async (): Promise<FileMap> => {
166	        const rows = await db.projectFile.findMany({
167	          where: { projectId: project.id, published: false, kind: "source" },
168	        });
169	        return Object.fromEntries(rows.map((f) => [f.path, f.content]));
170	      };
171	
172	      try {
173	        let request = prompt;
174	        let buildOutput: FileMap | null = null;
175	        let lastBuildError = "";
176	
177	        // Resolved ONCE, outside the retry loop, so a repair pass can never run
178	        // on a different engine than the attempt it is repairing.
179	        //
180	        // Only ever an upgrade: runAgent treats KODELY_ENGINE=sdk as an
181	        // absolute pin and ignores this, so the flag cannot revoke an
182	        // operator's deliberate choice to stay off the metered key. Bucketed on
183	        // user.id, not per build — splitting one person's builds across both
184	        // engines would contaminate any comparison between them.
185	        const engine = (await isEnabled(FLAGS.sdkEngine, user.id)) ? "sdk" : "api";
186	
187	        for (let attempt = 1; attempt <= MAX_BUILD_ATTEMPTS; attempt++) {
188	          if (abortController.signal.aborted) break;
189	
190	          const generator = runAgent({
191	            engine,
192	            history: project.messages.map((m) => ({
193	              role: m.role === "assistant" ? ("assistant" as const) : ("user" as const),
194	              content: m.content,
195	            })),
196	            request,
197	            files: await readSourceFiles(),
198	            kind,
199	            // Only attached on the very first turn of a project — a repair
200	            // retry re-sends the same `request` text but should not attach
201	            // the image again mid-loop.
202	            image: attempt === 1 ? image : undefined,
203	            signal: abortController.signal,
204	            onWrite: async (path, content) => {
205	              if (!normalizePath(path)) return false;
206	              await db.projectFile.upsert({
207	                where: {
208	                  projectId_path_published_kind: {
209	                    projectId: project.id,
210	                    path,
211	                    published: false,
212	                    kind: "source",
213	                  },
214	                },
215	                create: { projectId: project.id, path, content, published: false, kind: "source" },
216	                update: { content },
217	              });
218	              filesWritten++;
219	              return true;
220	            },
221	            onDelete: async (path) => {
222	              const { count } = await db.projectFile.deleteMany({
223	                where: { projectId: project.id, path, published: false, kind: "source" },
224	              });
225	              return count > 0;
226	            },
227	          });
228	
229	          for await (const event of generator) {
230	            if (event.type === "text") {
231	              lastReply += event.text;
232	              send(event);
233	            } else if (event.type === "file") {
234	              send(event);
235	            } else if (event.type === "status") {
236	              send(event);
237	            } else if (event.type === "progress") {
238	              // Collapse consecutive identical lines. A run of twelve Reads
239	              // narrates as one "Looking through the project" rather than
240	              // twelve, which would read as a stutter rather than progress.
241	              if (event.text !== lastProgress) {
242	                lastProgress = event.text;
243	                send(event);
244	              }
245	            } else if (event.type === "usage") {
246	              model = event.model;
247	              totals.inputTokens += event.inputTokens;
248	              totals.outputTokens += event.outputTokens;
249	              totals.cacheReadTokens += event.cacheReadTokens;
250	              totals.cacheWriteTokens += event.cacheWriteTokens;
251	            }
252	          }
253	
254	          if (abortController.signal.aborted) break;
255	
256	          try {
257	            send({ type: "progress", text: "Compiling the site" });
258	            buildOutput = await buildSite(await readSourceFiles());
259	            break; // compiled cleanly — done
260	          } catch (err) {
261	            lastBuildError = err instanceof BuildError ? err.message : String(err);
262	            if (attempt >= MAX_BUILD_ATTEMPTS) throw new Error(lastBuildError);
263	            repairAttempts++;
264	            // Clear the dedupe key: the repair pass legitimately repeats the
265	            // same lines, and suppressing them would look like a stall.
266	            lastProgress = "";
267	            send({ type: "status", text: "Build didn't compile — fixing it…" });
268	            request = `The last change failed to build. Fix it and keep the rest of the change. Build error:\n${lastBuildError}`;
269	          }
270	        }
271	
272	        if (abortController.signal.aborted || !buildOutput) {
273	          // Loop ended without a successful build and without throwing —
274	          // only reachable via the abort path (see the `break` above).
275	        } else {
276	          succeeded = true;
277	
278	          // Replace the compiled tree with the new build output.
279	          await db.$transaction([
280	            db.projectFile.deleteMany({ where: { projectId: project.id, published: false, kind: "build" } }),
281	            ...(Object.keys(buildOutput).length > 0
282	              ? [
283	                  db.projectFile.createMany({
284	                    data: Object.entries(buildOutput).map(([path, content]) => ({
285	                      projectId: project.id,
286	                      path,
287	                      content,
288	                      published: false,
289	                      kind: "build",
290	                    })),
291	                  }),
292	                ]
293	              : []),
294	          ]);
295	
296	          const micros = costMicros(model, totals);
297	          const credits = creditsFor(micros);
298	          // A zero charge writes no ledger row. The ledger is a financial
299	          // record; an entry that moves nothing is noise in a statement a
300	          // customer may one day be reading to understand their bill.
301	          const remaining =
302	            credits > 0
303	              ? await chargeForBuild(user.id, build.id, credits)
304	              : await getBalance(user.id);
305	
306	          const sourceFiles = await readSourceFiles();
307	          const filesSnapshot = { source: sourceFiles, build: buildOutput };
308	
309	          await db.build.update({
310	            where: { id: build.id },
311	            data: {
312	              status: "SUCCEEDED",
313	              model,
314	              endedAt: new Date(),
315	              inputTokens: totals.inputTokens,
316	              outputTokens: totals.outputTokens,
317	              cacheReadTokens: totals.cacheReadTokens,
318	              cacheWriteTokens: totals.cacheWriteTokens,
319	              filesWritten,
320	              repairAttempts,
321	              costMicros: micros,
322	              creditsCharged: credits,
323	              filesSnapshot,
324	            },
325	          });
326	
327	          track(EVENTS.buildSucceeded, {
328	            userId: user.id,
329	            props: {
330	              buildId: build.id,
331	              projectId: project.id,
332	              kind,
333	              model,
334	              repairAttempts,
335	              filesWritten,
336	              credits,
337	              remaining,
338	            },
339	          });
340	
341	          if (lastReply.trim()) {
342	            await db.message.create({
343	              data: { projectId: project.id, role: "assistant", content: lastReply.trim() },
344	            });
345	          }
346	          await db.project.update({ where: { id: project.id }, data: { updatedAt: new Date() } });
347	
348	          // buildId travels to the client so it can attach a rating to this
349	          // specific build (see app/api/feedback/route.ts).
350	          send({ type: "done", credits, remaining, filesWritten, buildId: build.id });
351	        }
352	
353	        if (!succeeded) {
354	          await db.build.update({
355	            where: { id: build.id },
356	            data: {
357	              status: "FAILED",
358	              endedAt: new Date(),
359	              error: abortController.signal.aborted ? "Client disconnected." : "Generation ended without producing output.",
360	              filesWritten,
361	              repairAttempts,
362	              creditsCharged: 0,
363	              // Record the model on failure too, when we got far enough to
364	              // learn it. It used to be written only on success, so every
365	              // failed build had a blank Model column — which made it
366	              // impossible to attribute a spike in failures to a model change,
367	              // exactly when you most need to.
368	              ...(model ? { model } : {}),
369	            },
370	          });
371	
372	          track(EVENTS.buildFailed, {
373	            userId: user.id,
374	            props: {
375	              buildId: build.id,
376	              projectId: project.id,
377	              kind,
378	              repairAttempts,
379	              reason: abortController.signal.aborted ? "aborted" : "no_output",
380	            },
381	          });
382	        }
383	      } catch (error) {
384	        // A build that fails is never charged — that is the product promise,
385	        // so the ledger is deliberately untouched on this path.
386	        const message =
387	          error instanceof Error ? error.message : "The build failed unexpectedly.";
388	        console.error("[kodely] build failed", build.id, error);
389	
390	        await db.build.update({
391	          where: { id: build.id },
392	          data: {
393	            status: "FAILED",
