  const clean = settleBuild(MODEL, [ATTEMPT1]);
  const repaired = settleBuild(MODEL, [ATTEMPT1, ATTEMPT2]);
  const oldPolicy = creditsFor(costMicros(MODEL, sumUsage([ATTEMPT1, ATTEMPT2])));

  console.log(
    `  clean   : cost ${usd(clean.costMicros)}  charged ${clean.credits} cr`,
  );
  console.log(
    `  repaired: cost ${usd(repaired.costMicros)}  charged ${repaired.credits} cr  waived ${repaired.waivedCredits} cr (${usd(repaired.waivedMicros)})`,
  );
  console.log(`  old policy would have charged: ${oldPolicy} cr`);

  check("repaired charges the same as a clean run", repaired.credits === clean.credits,
    `${repaired.credits} === ${clean.credits}`);
  check("repaired records MORE true cost than clean", repaired.costMicros > clean.costMicros,
    `${usd(repaired.costMicros)} > ${usd(clean.costMicros)}`);
  check("old policy would have charged strictly more", oldPolicy > repaired.credits,
    `${oldPolicy} > ${repaired.credits} (+${((oldPolicy / repaired.credits - 1) * 100).toFixed(1)}%)`);
  check("waivedCredits == old - new", repaired.waivedCredits === oldPolicy - repaired.credits);
  check("repairWaived flag set", repaired.repairWaived === true);
  check("clean build waives nothing", clean.waivedCredits === 0 && clean.repairWaived === false);
  check("costMicros == sum over attempts", repaired.costMicros === costMicros(MODEL, sumUsage([ATTEMPT1, ATTEMPT2])));
  check("billed + waived == total cost", repaired.billedMicros + repaired.waivedMicros === repaired.costMicros);

  // Rule 3 / creditsFor floor must survive.
  const unmetered = settleBuild(MODEL, [{ inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 }]);
  check("zero-telemetry run still charges 0", unmetered.credits === 0);
  const noAttempts = settleBuild(MODEL, []);
  check("no attempts at all settles to 0/0", noAttempts.credits === 0 && noAttempts.costMicros === 0);

  // Anti-gaming: a repair can never make the run cost the customer LESS than
  // the same first attempt on its own.
  check("repair never reduces the charge below a clean run", repaired.credits >= clean.credits);

  // ── Anti-gaming sweep: attempt 2 arbitrarily huge ──────────────────────
  const huge = settleBuild(MODEL, [ATTEMPT1, {
    inputTokens: 500_000, outputTokens: 400_000, cacheReadTokens: 5_000_000, cacheWriteTokens: 900_000,
  }]);
  check("charge is invariant to how big the repair pass gets",
    huge.credits === clean.credits, `${huge.credits} === ${clean.credits}`);
  check("...but its cost is still recorded", huge.costMicros > repaired.costMicros,
    usd(huge.costMicros));

  // ── DB round trip ───────────────────────────────────────────────────────
  console.log("\n=== 1. Real Postgres round trip ===");

  const stamp = `verify-${Date.now()}`;
  const user = await db.user.create({ data: { email: `${stamp}@example.invalid` } });
  const project = await db.project.create({ data: { userId: user.id, name: `${stamp}-project` } });
  const created = { userId: user.id, projectId: project.id };
  console.log(`  created user ${user.id} / project ${project.id}`);

  try {
    await grantCredits(user.id, 5000, "signup_grant");
    const startBalance = await getBalance(user.id);
    check("grant landed", startBalance === 5000, String(startBalance));

    // Writes a Build row with EXACTLY the field set app/api/generate/route.ts
    // writes on its success path.
    async function recordSuccess(attempts, repairAttempts) {
      const totals = sumUsage(attempts);
      const s = settleBuild(MODEL, attempts);
      const build = await db.build.create({
        data: { projectId: project.id, status: "RUNNING", model: "", prompt: stamp },
      });
      const remaining = s.credits > 0
        ? await chargeForBuild(user.id, build.id, s.credits)
        : await getBalance(user.id);
      await db.build.update({
        where: { id: build.id },
        data: {
          status: "SUCCEEDED",
          model: MODEL,
          endedAt: new Date(),
          inputTokens: totals.inputTokens,
          outputTokens: totals.outputTokens,
          cacheReadTokens: totals.cacheReadTokens,
          cacheWriteTokens: totals.cacheWriteTokens,
          filesWritten: 5,
          repairAttempts,
          costMicros: s.costMicros,
          creditsCharged: s.credits,
        },
      });
      return { build, s, remaining };
    }

    // Failure path: two attempts burned, nothing produced.
    async function recordFailure(attempts, repairAttempts) {
      const spent = sumUsage(attempts);
      const build = await db.build.create({
        data: { projectId: project.id, status: "RUNNING", model: "", prompt: stamp },
      });
      await db.build.update({
        where: { id: build.id },
        data: {
          status: "FAILED",
          endedAt: new Date(),
          error: "did not compile",
          filesWritten: 3,
          repairAttempts,
          creditsCharged: 0,
          inputTokens: spent.inputTokens,
          outputTokens: spent.outputTokens,
          cacheReadTokens: spent.cacheReadTokens,
          cacheWriteTokens: spent.cacheWriteTokens,
          costMicros: costMicros(MODEL, spent),
          model: MODEL,
        },
      });
      return build;
    }

    const A = await recordSuccess([ATTEMPT1], 0);              // clean
    const B = await recordSuccess([ATTEMPT1, ATTEMPT2], 1);    // repaired, succeeded
    const C = await recordFailure([ATTEMPT1, ATTEMPT2], 1);    // repaired, still failed

    // Read back from Postgres — not from memory.
    const rows = await db.build.findMany({
      where: { projectId: project.id },
      orderBy: { createdAt: "asc" },
      select: {
        id: true, status: true, repairAttempts: true, costMicros: true,
        creditsCharged: true, inputTokens: true, outputTokens: true,
        cacheReadTokens: true, cacheWriteTokens: true,
      },
    });
    const dbA = rows.find((r) => r.id === A.build.id);
    const dbB = rows.find((r) => r.id === B.build.id);
    const dbC = rows.find((r) => r.id === C.id);

    console.log(`  A clean    : cost ${usd(dbA.costMicros)}  charged ${dbA.creditsCharged} cr  repairs ${dbA.repairAttempts}`);
    console.log(`  B repaired : cost ${usd(dbB.costMicros)}  charged ${dbB.creditsCharged} cr  repairs ${dbB.repairAttempts}`);
    console.log(`  C failed   : cost ${usd(dbC.costMicros)}  charged ${dbC.creditsCharged} cr  repairs ${dbC.repairAttempts}`);

    check("B charged the same as A", dbB.creditsCharged === dbA.creditsCharged,
      `${dbB.creditsCharged} === ${dbA.creditsCharged}`);
    check("B's recorded cost is the WHOLE run, not the charged half",
      dbB.costMicros === costMicros(MODEL, sumUsage([ATTEMPT1, ATTEMPT2])),
      usd(dbB.costMicros));
    check("B's recorded cost exceeds A's", dbB.costMicros > dbA.costMicros);
    check("B's token columns are the whole run",
      dbB.outputTokens === ATTEMPT1.outputTokens + ATTEMPT2.outputTokens);
    check("B is under-recovered by exactly the waived amount",
      dbB.costMicros - dbB.creditsCharged * MICROS_PER_CREDIT > 0,
      `unrecovered ${usd(dbB.costMicros - dbB.creditsCharged * MICROS_PER_CREDIT)}`);
    check("A is fully recovered (rounding only)",
      dbA.creditsCharged * MICROS_PER_CREDIT - dbA.costMicros >= 0 &&
      dbA.creditsCharged * MICROS_PER_CREDIT - dbA.costMicros < MICROS_PER_CREDIT,
      `${usd(dbA.creditsCharged * MICROS_PER_CREDIT - dbA.costMicros)}`);
    check("failed build charged zero (rule 3 intact)", dbC.creditsCharged === 0);
    check("failed build still records its true cost", dbC.costMicros > 0, usd(dbC.costMicros));
    check("repairAttempts preserved on all three",
      dbA.repairAttempts === 0 && dbB.repairAttempts === 1 && dbC.repairAttempts === 1);

    // ── Ledger ────────────────────────────────────────────────────────────
    const ledger = await db.creditLedger.findMany({
      where: { userId: user.id },
      orderBy: [{ createdAt: "asc" }, { id: "asc" }],
      select: { delta: true, reason: true, buildId: true, balanceAfter: true },
    });
    console.log("  ledger:", ledger.map((l) => `${l.reason} ${l.delta > 0 ? "+" : ""}${l.delta} -> ${l.balanceAfter}`).join(" | "));

    const buildRows = ledger.filter((l) => l.buildId);
    check("exactly two charge rows (the failed build wrote none)", buildRows.length === 2);
    check('every charge row still reads reason "build"',
      buildRows.every((l) => l.reason === "build"),
      "so describeReason() still renders 'Site build'");
    check("charge rows match creditsCharged",
      buildRows.find((l) => l.buildId === A.build.id).delta === -dbA.creditsCharged &&
      buildRows.find((l) => l.buildId === B.build.id).delta === -dbB.creditsCharged);
    const finalBalance = await getBalance(user.id);
    check("balance chain is consistent",
      finalBalance === 5000 - dbA.creditsCharged - dbB.creditsCharged,
      String(finalBalance));

    const avg = await averageBuildCredits(user.id);
    check("averageBuildCredits sees both charged builds", avg === dbA.creditsCharged, String(avg));

    // ── Metrics still work ────────────────────────────────────────────────
    console.log("\n=== 2. Metrics that must not regress ===");
    const green = await greenBuildRate(30);
    console.log(`  greenBuildRate: ${green.firstTry}/${green.succeeded} = ${green.rate}%`);
    check("greenBuildRate counts B as NOT first-try", green.succeeded >= 2 && green.firstTry < green.succeeded);

    const [recovery] = await db.$queryRawUnsafe(`
      SELECT COALESCE(SUM(b."costMicros"),0)::bigint AS cost,
             COALESCE(SUM(b."creditsCharged"),0)::bigint AS credits,
             COALESCE(SUM(b."costMicros") FILTER (WHERE b."creditsCharged" = 0),0)::bigint AS freecost
      FROM "Build" b WHERE b."projectId" = $1`, project.id);
    const cost = Number(recovery.cost);
    const recovered = Number(recovery.credits) * MICROS_PER_CREDIT;
    console.log(`  admin view: cost ${usd(cost)}  recovered ${usd(recovered)}  given away ${usd(Number(recovery.freecost))}`);
    check("admin sees the full truth of what we spent",
      cost === dbA.costMicros + dbB.costMicros + dbC.costMicros);
    check("admin sees recovery below cost (the absorbed repair is visible)", recovered < cost,
      `shortfall ${usd(cost - recovered)}`);

    // ── What the SSE `done` event carries ─────────────────────────────────
    console.log("\n=== 3. done event payload ===");
    const doneClean = { type: "done", credits: A.s.credits, remaining: 5000 - A.s.credits, filesWritten: 5, buildId: A.build.id, repairAttempts: 0, repairWaived: A.s.repairWaived, waivedCredits: A.s.waivedCredits };
    const doneRepaired = { type: "done", credits: B.s.credits, remaining: B.remaining, filesWritten: 5, buildId: B.build.id, repairAttempts: 1, repairWaived: B.s.repairWaived, waivedCredits: B.s.waivedCredits };
    console.log("  clean   :", JSON.stringify(doneClean));
    console.log("  repaired:", JSON.stringify(doneRepaired));
    check("done says the repair was free", doneRepaired.repairWaived === true && doneRepaired.waivedCredits > 0);
    check("done on a clean build claims nothing", doneClean.repairWaived === false && doneClean.waivedCredits === 0);
  } finally {
    console.log("\n=== 4. Cleanup ===");
    await db.creditLedger.deleteMany({ where: { userId: created.userId } });
    await db.project.deleteMany({ where: { id: created.projectId } });
    await db.user.deleteMany({ where: { id: created.userId } });
    const leftUsers = await db.user.count({ where: { id: created.userId } });
    const leftBuilds = await db.build.count({ where: { projectId: created.projectId } });
    const leftLedger = await db.creditLedger.count({ where: { userId: created.userId } });
    check("all test rows removed", leftUsers === 0 && leftBuilds === 0 && leftLedger === 0);
    const remainingBuilds = await db.build.count();
    console.log(`  builds left in DB: ${remainingBuilds}`);
  }

  console.log(`\n${pass} passed, ${fail} failed\n`);
  await db.$disconnect();
  process.exit(fail === 0 ? 0 : 1);
}

main().catch(async (e) => {
  console.error(e);
  await db.$disconnect();
  process.exit(1);
});

