// attempt, pushed before the generator runs, accumulated per usage event.
// The SDK engine can yield MORE THAN ONE usage event per attempt, so this
// feeds two into attempt 1 to prove they land in the same bucket rather
// than splitting across attempts.
console.log("\n=== 0b. Route accumulator replay ===");
{
  const stream = [
    [ // attempt 1, two usage events
      { type: "usage", model: MODEL, inputTokens: 7_000, outputTokens: 11_000, cacheReadTokens: 160_000, cacheWriteTokens: 25_000 },
      { type: "usage", model: MODEL, inputTokens: 5_000, outputTokens: 7_000, cacheReadTokens: 100_000, cacheWriteTokens: 15_000 },
    ],
    [ATTEMPT2].map((u) => ({ type: "usage", model: MODEL, ...u })),
  ];
  const attemptUsage = [];
  let model = "";
  for (const events of stream) {
    const attemptTotals = { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 };
    attemptUsage.push(attemptTotals);
    for (const e of events) {
      model = e.model;
      attemptTotals.inputTokens += e.inputTokens;
      attemptTotals.outputTokens += e.outputTokens;
      attemptTotals.cacheReadTokens += e.cacheReadTokens;
      attemptTotals.cacheWriteTokens += e.cacheWriteTokens;
    }
  }
  check("one bucket per attempt", attemptUsage.length === 2);
  check("both of attempt 1's usage events landed in attempt 1",
    attemptUsage[0].outputTokens === 18_000 && attemptUsage[0].inputTokens === 12_000);
